SELECT customer_id, DATE_TRUNC('MONTH', start_date) AS activity_month, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, SIZE(COLLECT_SET(status)) AS num_status, COUNT(*) FILTER (WHERE plan = 'basic') AS basic_rows, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY SIZE(COLLECT_SET(status)) DESC) AS num_status_percent_rank FROM subscriptions GROUP BY 1, 2 ORDER BY num_status DESC NULLS FIRST;
